package domain

import (
	"time"

	"github.com/google/uuid"
	"gorm.io/datatypes"
)

// AIAnalysisSubmission is the record of one successful AI analysis submission
// and the idempotency-key store of /internal/ai-analysis/submit (spec §2.2,
// §6.4). submission_id is generated by the caller.
//
// activity_id is unique: at most one successful submission completes an
// Activity. Foreign-key actions are the project default (ON UPDATE CASCADE /
// ON DELETE RESTRICT); the spec gives none.
type AIAnalysisSubmission struct {
	SubmissionID    uuid.UUID      `gorm:"type:uuid;primaryKey" json:"submission_id"`
	ActivityID      uuid.UUID      `gorm:"type:uuid;not null;uniqueIndex" json:"activity_id"`
	RequestPayload  datatypes.JSON `gorm:"type:jsonb;not null" json:"request_payload"`
	RequestHash     string         `gorm:"not null" json:"request_hash"`
	ResponsePayload datatypes.JSON `gorm:"type:jsonb;not null" json:"response_payload"`
	CreatedAt       time.Time      `json:"created_at"`

	Activity *Activity `gorm:"foreignKey:ActivityID;references:ID;constraint:OnUpdate:CASCADE,OnDelete:RESTRICT" json:"-" swaggerignore:"true"`
}

// ChatbotUsageKind is the chatbot session type a usage row records (spec §2.2).
type ChatbotUsageKind string

const (
	ChatbotUsageKindFeedback     ChatbotUsageKind = "feedback"
	ChatbotUsageKindReviewStage1 ChatbotUsageKind = "review_stage1"
	ChatbotUsageKindReviewStage2 ChatbotUsageKind = "review_stage2"
	ChatbotUsageKindHistorical   ChatbotUsageKind = "historical"
)

// ChatbotUsage is the usage record of one finished chatbot session (spec §2.2).
// It is written from day 1 as the data foundation of a later freemium entry
// point, even though the MVP shows it to nobody.
//
// activity_id is nullable: historical sessions have no Activity. Foreign-key
// actions are the project default (ON UPDATE CASCADE / ON DELETE RESTRICT); the
// spec gives none.
type ChatbotUsage struct {
	ID           uuid.UUID        `gorm:"type:uuid;primaryKey" json:"id"`
	UserID       uuid.UUID        `gorm:"type:uuid;not null;index" json:"user_id"`
	ActivityID   *uuid.UUID       `gorm:"type:uuid;index" json:"activity_id"`
	Kind         ChatbotUsageKind `gorm:"not null" json:"kind"`
	MessageCount int              `gorm:"not null" json:"message_count"`
	TokensIn     int              `gorm:"not null" json:"tokens_in"`
	TokensOut    int              `gorm:"not null" json:"tokens_out"`
	CreatedAt    time.Time        `gorm:"index" json:"created_at"`

	User     *User     `gorm:"foreignKey:UserID;references:ID;constraint:OnUpdate:CASCADE,OnDelete:RESTRICT" json:"-" swaggerignore:"true"`
	Activity *Activity `gorm:"foreignKey:ActivityID;references:ID;constraint:OnUpdate:CASCADE,OnDelete:RESTRICT" json:"-" swaggerignore:"true"`
}
